# -*- coding: utf-8 -*-
import re

with open('app/src/main/java/com/example/data/WorshipData.kt', 'r', encoding='utf-8') as f:
    content = f.read()

match = re.search(r'val sahifaSajjadiya = listOf\((.*?)\)\s+val generalPrayers =', content, re.DOTALL)
if not match:
    print("Could not find sahifaSajjadiya block!")
    exit(1)

block = match.group(1)
elements = re.split(r'(?=Pair\(\"الدعاء)', block)
elements = [e.strip() for e in elements if e.strip()]

for idx in range(len(elements)):
    elements[idx] = elements[idx].rstrip()
    if elements[idx].endswith(','):
        elements[idx] = elements[idx][:-1].rstrip()

text_15 = """بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ
أللَّهُمَّ يَا مَنْ بِرَحْمَتِهِ يَسْتَغِيثُ الْمُذْنِبُونَ، وَيَا مَنْ إلَى ذِكْرِ إحْسَانِهِ يَفْزَعُ الْمُضْطَرُّونَ، وَيَا مَنْ لِخِيفَتِهِ يَنْتَحِبُ الْخَاطِئُونَ، يَا اُنْسَ كُلِّ مُسْتَوْحِش غَرِيبِ، وَيَا فَرَجَ كُلِّ مَكْرُوب كَئِيب، وَيَا غَوْثَ كُلِّ مَخْذُوَل فَرِيد، وَيَا عَضُدَ كُلِّ مُحْتَاج طَرِيد.
أَنْتَ الَّذِي وَسِعْتَ كُلَّ شَيْء رَحْمَةً وَعِلْماً، وَأَنْتَ الَّذِي جَعَلْتَ لِكُلِّ مَخْلُوق فِي نِعَمِكَ سَهْماً، وَأَنْتَ الَّذِيْ عَفْوُهُ أَعْلَى مِنْ عِقَابِهِ، وَأَنْتَ الَّذِي تَسْعَى رَحْمَتُهُ أَمَامَ غَضَبِهِ، وَأَنْتَ الَّذِي عَطَآؤُهُ أكْثَرُ مِنْ مَنْعِهِ، وَأَنْتَ الَّذِيْ اتَّسَعَ الْخَلاَئِقُ كُلُّهُمْ فِي وُسْعِهِ، وَأَنْتَ الَّذِي لا يَرْغَبُ فِي جَزَاءِ مَنْ أَعْطَاهُ، وَأَنْتَ الَّذِي لا يُفْرِطُ فِي عِقَابِ مَنْ عَصَاهُ.
وَأَنَا يَا إلهِي عَبْدُكَ الَّذِي أَمَرْتَهُ بِالدُّعاءِ فَقَالَ: لَبَّيْكَ وَسَعْدَيْكَ، هَا أَنَا ذَا يَا رَبِّ مَطْرُوحٌ بَيْنَ يَدَيْكَ، أَنَا الَّذِي أَوْقَرَتِ الْخَطَايَا ظَهْرَهُ، وَأَنا الَّذِي أَفْنَتِ الذُّنُوبُ عُمْرَهُ، وَأَنَا الَّذِي بِجَهْلِهِ عَصاكَ وَلَمْ تَكُنْ أَهْلاً مِنْهُ لِذَاكَ.
هَلْ أَنْتَ يَا إلهِي رَاحِمٌ مَنْ دَعَاكَ فَأُبْلِغَ فِي الدُّعَاءِ أَمْ أَنْتَ غَافِرٌ لِمَنْ بَكَاكَ فَأُسْرِعَ فِي الْبُكَاءِ أَمْ أَنْتَ مُتَجَاوِزٌ عَمَّنْ عَفَّرَ لَكَ وَجْهَهُ تَذَلُّلاً أَم أَنْتَ مُغْن مَنْ شَكَا إلَيْكَ فَقْرَهُ تَوَكُّلاً؟
إلهِي لاَ تُخيِّبْ مَنْ لا يَجدُ مُعْطِياً غَيْرَكَ، وَلاَ تَخْذُلْ مَنْ لا يَسْتَغْنِي عَنْكَ بِأَحَد دُونَكَ.
إلهِي فَصَلِّ عَلَى مُحَمَّد وَآلِهِ وَلاَ تُعْرِضْ عَنِّي وَقَدْ أَقْبَلْتُ عَلَيْكَ، وَلا تَحْرِمْنِي وَقَـدْ رَغِبْتُ إلَيْكَ، وَلا تَجْبَهْنِي بِالرَّدِّ وَقَدْ انْتَصَبْتُ بَيْنَ يَدَيْكَ.
أَنْتَ الَّذِي وَصَفْتَ نَفْسَكَ بِالرَّحْمَةِ، فَصَلِّ عَلَى مُحَمَّد وَآلِهِ وَارْحَمْنِي، وَأَنْتَ الَّذِي سَمَّيْتَ نَفْسَكَ بِالعَفْوِ، فَاعْفُ عَنِّي.
قَـدْ تَرَى يَـا إلهِي فَيْضَ دَمْعِي مِنْ خِيفَتِكَ، وَوَجِيبَ قَلْبِي مِنْ خَشْيَتِكَ، وَانْتِفَاضَ جَوَارِحِي مِنْ هَيْبَتِكَ، كُلُّ ذَلِكَ حَياءً مِنِّي لِسُوءِ عَمَلِي، وَلِذَاكَ خَمَدَ صَوْتِي عَنِ الْجَأرِ إلَيْكَ، وَكَلَّ لِسَانِي عَنْ مُنَاجَاتِكَ يَا إلهِي.
فَلَكَ الْحَمْدُ، فَكَم مِنْ غَائِبَة سَتَرْتَهَا عَلَيَّ فَلَم تَفْضَحْنِي، وَكَمْ مِنْ ذنْبِ غَطَّيْتَهُ عَلَيَّ فَلَمْ تَشْهَرْنِي، وَكَمْ مِنْ شَائِبَة أَلْمَمْتُ بِهَا فَلَمْ تَهْتِكْ عَنِّي سِتْرَهَا، وَلَمْ تُقَلِّدْنِي مَكْرُوهَ شَنَارِهَا، وَلَمْ تُبْدِ سَوْأَتَهَا لِمَنْ يَلْتَمِسُ مَعَايِبِي مِنْ جِيْرَتِي، وَحَسَدَةِ نِعْمَتِكَ عِنْدِي، ثُمَّ لَمْ يَنْهَنِي ذَلِكَ عَنْ أَنْ جَرَيْتُ إلَى سُوءِ مَا عَهِدْتَ مِنّي فَمَنْ أَجْهَلُ مِنِّي يَا إلهِيْ بِرُشْدِهِ وَمَنْ أَغْفَلُ مِنِّي عَنْ حَظِّهِ وَمَنْ أَبْعَدُ مِنِّي مِنِ اسْتِصْلاَحِ نَفْسِهِ حِيْنَ اُنْفِقُ مَا أَجْرَيْتَ عَلَيَّ مِنْ رِزْقِكَ فِيمَا نَهَيْتَنِي عَنْهُ مِنْ مَعْصِيَتِكَ وَمَنْ أَبْعَدُ غَوْراً فِي الْبَاطِلِ وَأَشَدُّ إقْدَاماً عَلَى السُّوءِ مِنّي حِينَ أَقِفُ بَيْنَ دَعْوَتِكَ وَدَعْوَتِ الشَّيْطَانِ، فَـأتَّبعُ دَعْوَتَهُ عَلَى غَيْرِ عَمىً مِنّي فِيْ مَعْرِفَة بِهِ، وَلا نِسْيَان مِنْ حِفْظِي لَهُ وَأَنَا حِينَئِذ مُوقِنٌ بِأَنَّ مُنْتَهَى دَعْوَتِكَ إلَى الْجَنَّةِ وَمُنْتَهَى دَعْوَتِهِ إلَى النَّارِ سُبْحَانَكَ مَا أَعْجَبَ مَا أَشْهَدُ بِهِ عَلَى نَفْسِي وَاُعَدِّدُهُ مِنْ مَكْتُوْمِ أَمْرِي، وَأَعْجَبُ مِنْ ذلِكَ أَنَاتُكَ عَنِّي وَإبْطآؤُكَ عَنْ مُعَاجَلَتِي وَلَيْسَ ذلِكَ مِنْ كَرَمِي عَلَيْكَ بَلْ تَأَنِّياً مِنْكَ لِي، وَتَفَضُّلاً مِنْكَ عَلَيَّ، لانْ أَرْتَـدِعَ عَنْ مَعْصِيَتِكَ الْمُسْخِطَةِ وَاُقْلِعَ عَنْ سَيِّئَـاتِي الْمُخْلِقَةِ وَلِاَنَّ عَفْوَكَ عَنّي أَحَبُّ إلَيْكَ مِنْ عُقُوبَتِي، بَلْ أَنَا يَا إلهِي أكْثَرُ ذُنُوباً وَأَقْبَحُ آثاراً وَأَشْنَعُ أَفْعَالاً وَأَشَدُّ فِي الْباطِلِ تَهَوُّراً وَأَضْعَفُ عِنْدَ طَاعَتِكَ تَيَقُّظاً، وَأَقَلُّ لِوَعِيْدِكَ انْتِبَاهاً وَارْتِقَاباً مِنْ أَنْ اُحْصِيَ لَكَ عُيُوبِي، أَوْ أَقْدِرَ عَلَى ذِكْرِ ذُنُوبِي وَإنَّمَا اُوبِّخُ بِهَذا نَفْسِي طَمَعَـاً فِي رَأْفَتِكَ الَّتِي بِهَـا صَلاَحُ أَمْرِ الْمُذْنِبِينَ، وَرَجَاءً لِرَحْمَتِكَ الَّتِي بِهَا فَكَاكُ رِقَابِ الْخَاطِئِينَ. اللَّهُمَّ وَهَذِهِ رَقَبَتِي قَدْ أَرَقَّتْهَا الذُّنُوبُ، فَصَلِّ عَلَى مُحَمَّد وَآلِهِ وَأَعْتِقْهَا بِعَفْوِكَ، وَهَذَا ظَهْرِي قَدْ أَثْقَلَتْهُ الْخَطَايَـا، فَصَلِّ عَلَى مُحَمَّد وَآلِهِ وَخَفِّفْ عَنْهُ بِمَنِّكَ.
يَا إلهِي لَوْ بَكَيْتُ إلَيْكَ حَتَّى تَسْقُطَ أَشْفَارُ عَيْنَيَّ، وَانْتَحَبْتُ حَتَّى يَنْقَطِعَ صَوْتِي، وَقُمْتُ لَكَ حَتَّى تَتَنَشَّرَ قَدَمَايَ، وَرَكَعْتُ لَكَ حَتَّى يَنْخَلِعَ صُلْبِي، وَسَجَدْتُ لَكَ حَتَّى تَتَفَقَّأَ حَدَقَتَايَ، وَأكَلْتُ تُرَابَ الارْضِ طُولَ عُمْرِي، وَشَرِبْتُ مَاءَ الرَّمَادِ آخِرَ دَهْرِي وَذَكَرْتُكَ فِي خِلاَلِ ذَلِكَ حَتَّى يَكِلَّ لِسَانِي ثُمَّ لَمْ أَرْفَعْ طَرْفِي إلَى آفَاقِ السَّمَاءِ اسْتِحْيَاءً مِنْكَ مَا اسْتَوْجَبْتُ بِذَلِكَ مَحْوَ سَيِّئَة وَاحِـدَة مِنْ سَيِّئـاتِي، وَإنْ كُنْتَ تَغْفِـرُ لِي حِيْنَ أَسْتَوْجِبُ مَغْفِرَتَكَ وَتَعْفُوعَنِّي حِينَ أَسْتَحِقُّ عَفْوَكَ فَإنَّ ذَلِكَ غَيْرُ وَاجِب لِيْ بِاسْتِحْقَاق، وَلا أَنَا أَهْلٌ لَهُ بِـاسْتِيجَاب إذْ كَـانَ جَزَائِي مِنْـكَ فِي أَوَّلِ مَا عَصَيْتُكَ النَّارَ؛ فَإنْ تُعَذِّبْنِي، فَأَنْتَ غَيْرُ ظَالِم لِيْ.
إلهِي فَـإذْ قَـدْ تَغَمَّـدْتَنِي بِسِتْـرِكَ فَلَمْ تَفْضَحْنِي وَتَـأَنَّيْتَنِي بِكَـرَمِـكَ فَلَمْ تُعَـاجِلْنِي وَحَلُمْتَ عَنِّي بِتَفَضُّلِكَ، فَلَمْ تُغَيِّـرْ نِعْمَتَـكَ عَلَيَّ، وَلَمْ تُكَـدِّرْ مَعْرُوفَكَ عِنْدِي فَارْحَمْ طُولَ تَضَرُّعِيْ وَشِـدَّةَ مَسْكَنَتِي وَسُوءَ مَوْقِفِيْ.
اللَّهُمَّ صَلِّ عَلَى مُحَمَّد وَآلِهِ وَقِنِي مِنَ الْمَعَاصِي وَاسْتَعْمِلْنِي بِالطَّاعَةِ، وَارْزُقْنِي حُسْنَ الاِنابَةِ وَطَهِّرْنِي بِالتَّـوْبَةِ، وَأَيِّـدْنِي بِالْعِصْمَةِ وَاسْتَصْلِحْنِي بِالْعَافِيَةِ وَأَذِقْنِي حَلاَوَةَ الْمَغْفِـرَةِ، وَاجْعَلْنِي طَلِيقَ عَفْـوِكَ، وَعَتِيقَ رَحْمَتِكَ وَاكْتُبْ لِي أَمَاناً مِنْ سَخَطِكَ وَبَشِّرْنِي بِذلِكَ فِي الْعَاجِلِ دُونَ الاجِلِ بُشْرى أَعْرِفُهَا وَعَرِّفْنِي فِيهِ عَلاَمَةً أَتَبَيَّنُهَا إنَّ ذلِكَ لاَ يَضيقُ عَلَيْكَ فِي وُسْعِكَ، وَلا يَتَأَّدُكَ فِي قُدْرَتِكَ، وَلا يَتَصَعَّدُكَ فِي أناتِكَ، وَلا يَؤودُك فِي جَزِيلِ هِباتِكَ الَّتِي دَلَّتْ عَلَيْهَا آيَاتُكَ إنَّكَ تَفْعَلُ مَا تَشَاءُ وَتَحكُمُ مَا تُرِيدُ، إنَّكَ عَلَى كُلِّ شَيْء قَدِيرٌ.
وصَلَّى اللهُ عَلَى مُحَمَّد وَآلِهِ المُطَهَّرِينَ."""

text_16 = """بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ
أَللَّهُمَّ إنَّا نَعُوذُ بِكَ مِنْ نَزَغَـاتِ الشَّيْطَانِ الرَّجِيمِ وَكَيْدِهِ وَمَكَائِدِهِ، وَمِنَ الثِّقَةِ بِأَمَـانِيِّهِ وَمَوَاعِيدِهِ وَغُرُورِهِ وَمَصَائِدِهِ، وَأَنْ يُطْمِعَ نَفْسَهُ فِي إضْلاَلِنَا عَنْ طَاعَتِكَ وَامْتِهَانِنَا بِمَعْصِيَتِكَ، أَوْ أَنْ يَحْسُنَ عِنْدَنَا مَا حَسَّنَ لَنَا، أَوْ أَنْ يَثْقُلَ عَلَيْنَا مَا كَرَّهَ إلَيْنَا. أللَّهُمَّ اخْسَأْهُ عَنَّا بِعِبَادَتِكَ، وَاكْبِتْهُ بِدُؤوبِنَا فِي مَحَبَّتِكَ، وَاجْعَلْ بَيْنَنَا وَبَيْنَهُ سِتْراً لاَ يَهْتِكُهُ، وَرَدْماً مُصْمِتاً لا يَفْتُقُهُ.
أللَّهُمَّ صَـلِّ عَلَى مُحَمَّد وَآلِـهِ، وَاشْغَلْهُ عَنَّا بِبَعْضِ أَعْدَائِكَ، وَاعْصِمْنَا مِنْهُ بِحُسْنِ رِعَايَتِكَ، وَاكْفِنَا خَتْرَهُ، وَوَلِّنَا ظَهْرَهُ، وَاقْطَعْ عَنَّا إثْرَهُ.
اللَّهُمَّ صَلِّ عَلَى مُحَمَّد وَآلِهِ وَأَمْتِعْنَا مِنَ الْهُدَى، بِمِثْلِ ضَلاَلَتِهِ، وَزَوِّدْنَا مِنَ التَّقْوَى ضِدَّ غَوَايَتِهِ، وَاسْلُكْ بِنَـا مِنَ التُّقى خِـلافَ سَبِيلِهِ مِنَ الـرَّدى.
أللَّهُمَّ لاَ تَجْعَلْ لَهُ فِي قُلُوبِنَا مَدْخَلاً وَلاَ تُوطِنَنَّ لَهُ فِيمَا لَدَيْنَا مَنْزِلاً.
اللَّهُمَّ وَمَا سَوَّلَ لَنَا مِنْ بَاطِل فَعَرِّفْنَاهُ وَإذَا عَرَّفْتَنَاهُ فَقِنَاهُ، وَبَصِّرْنَا مَا نُكَايِدُهُ بِهِ، وَأَلْهِمْنَا مَا نُعِدُّهُ، وَأَيْقِظْنَا عَنْ سِنَةِ الْغَفْلَةِ بِالرُّكُونِ إلَيْهِ وَأَحْسِنْ بِتَوْفِيقِكَ عَوْنَنَا عَلَيْهِ.
اللَّهُمَّ وَأَشْرِبْ قُلُوبَنَـا إنْكَارَ عَمَلِهِ، وَالْـطُفْ لَنَا فِي نَقضِ حِيَلِهِ.
أللَّهُمَّ صَلِّ عَلَى مُحَمَّد وَآلِهِ وَحَوِّلْ سُلْطَانَهُ عَنَّا، وَاقْطَعْ رَجَاءَهُ مِنَّا، وادْرَأْه عَنِ الْوُلُوعِ بِنَا.
اللَّهُمَّ صَلِّ عَلَى مُحَمَّد وَآلِهِ وَاجْعَلْ آباءَنَا وَاُمَّهَاتِنَا وَأَوْلاَدَنَا وَأَهَالِينَا وَذَوِي أَرْحَامِنَا وَقَرَابَاتِنَا وَجِيْرَانَنَا مِنَ الْمُؤْمِنِينَ وَالْمُؤْمِنَـاتِ مِنْهُ فِي حِـرْز حَـارِز، وَحِصْن حَافِظ، وَكَهْف مَانِع، وَألْبِسْهُمْ مِنْهُ جُنَناً وَاقِيَةً، وَأَعْطِهِمْ عَلَيْهِ أَسْلِحَةً مَاضِيَةً.
أللَّهُمَّ وَاعْمُمْ بِذلِكَ مَنْ شَهِدَ لَكَ بِالرُّبُوبِيَّةِ، وَأَخْلَصَ لَكَ بِالْوَحْدَانِيَّةِ، وَعَادَاهُ لَكَ بِحَقِيقَةِ الْعُبُودِيَّة، وَاسْتَظْهَرَ بِكَ عَلَيْهِ فِي مَعْرِفَةِ الْعُلُومِ الرَّبَّانِيَّةِ.
اللَّهُمَّ احْلُلْ مَا عَقَدَ، وَافْتقْ مَا رَتَقَ، وَافسَخ مَا دَبَّرَ، وَثَبِّطْهُ إذَا عَزَمَ، وَانْقُضْ مَا أَبْرَمَ. اللَّهُمَّ وَاهْزِمْ جُنْدَهُ وَأَبْطِلْ كَيْدَهُ وَاهْدِمْ كَهْفَهُ وَأَرْغِمْ أَنْفَهُ.
اللَّهُمَّ اجْعَلْنَا فِي نَظْم أَعْدَآئِهِ وَاعْزِلْنَا عَنْ عِدَادِ أَوْلِيَائِهِ، لا نُطِيعُ لَهُ إذَا اسْتَهْوَانَا، وَلا نَسْتَجِيبُ لَهُ إذَا دَعَانَا نَأْمُرُ بِمُنَاوَاتِهِ مَنْ أَطَاعَ أَمْرَنَا وَنَعِظُ عَنْ مُتَابَعَتِهِ مَنِ اتَّبَعَ زَجْرَنَا. اللَّهُمَّ صَلِّ عَلَى مُحَمَّد وَآلِهِ خَاتَمِ النَّبِيِّينَ وَسَيِّدِ الْمُرْسَلِينَ وَعَلَى أَهْلِ بَيْتِهِ الطَّيِّبِينَ الـطَّاهِرِينَ وَأَعِذْنَا وَأَهَـالِينَا وَإخْـوَانَنَا وَجَمِيـعَ الْمُؤْمِنِينَ وَالْمُؤْمِنَاتِ مِمَّا اسْتَعَذْنَا مِنْهُ، وَأَجِرْنَا مِمَّا اسْتَجَرْنَا بِكَ مِنْ خَوْفِهِ وَاسْمَعْ لَنَا مَا دَعَوْنَا بِهِ وَأَعْطِنَا مَا أَغْفَلْنَاهُ وَاحْفَظْ لَنَا مَا نَسِيْنَاهُ، وَصَيِّرْنَا، بِذَلِكَ فِي دَرَجَاتِ الصَّالِحِينَ وَمَـرَاتِبِ الْمُؤْمِنِينَ آمينَ رَبَّ الْعَالَمِينَ."""

text_17 = """بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ
أَللَّهُمَّ لَكَ الْحَمْدُ عَلَى حُسْنِ قَضَائِكَ، وَبِمَا صَرَفْتَ عَنِّي مِنْ بَلائِكَ، فَلاَتَجْعَـلْ حَظِّي مِنْ رَحْمَتِكَ مَا عَجَّلْتَ لِي مِنْ عَافِيَتِكَ فَاكُونَ قَدْ شَقِيتُ بِمَا أَحْبَبْتُ وَسَعِدَ غَيْرِي بِمَا كَرِهْتُ، وَإنْ يَكُنْ مَا ظَلِلْتُ فِيهِ أَوْ بِتُّ فِيهِ مِنْ هَذِهِ الْعَافِيَةِ بَيْنَ يَدَيْ بَلاء لاَ يَنْقَطِعُ، وَوِزْر لاَ يَرْتَفِعُ فَقَدِّمْ لِي مَا أَخَّرْتَ وَأَخِّرْ عَنّي مَا قَدَّمْتَ فَغَيْرُ كَثِير مَا عَاقِبَتُهُ الْفَنَاءُ، وَغَيْرُ قَلِيل مَا عَاقِبَتُهُ الْبَقَاءُ. وَصَلِّ عَلَى مُحَمَّد وَآلِهِ."""

text_18 = """بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ
أللَّهُمَّ اسْقِنَـا الْغَيْثَ، وَانْشُرْ عَلَيْنَـا رَحْمَتَـكَ بِغَيْثِكَ الْمُغْدِقِ مِنَ الْسَّحَابِ الْمُنْسَـاقِ لِنَبَاتِ أَرْضِـكَ الْمُونِقِ فِي جَمِيـعِ الافَاقِ، وَامْنُنْ عَلَى عِبَادِكَ بِإينَاعِ الثَّمَرَةِ، وأَحْيِ بِلاَدَكَ بِبُلُوغِ الزَّهَرَةِ.
وَأَشْهِدْ مَلائِكَتَكَ الْكِرَامَ السَّفَرَةَ بِسَقْي مِنْكَ نَافِع دَائِم غُزْرُهُ وَاسِعٌ دِرَرُهُ وَابِل سَرِيع عَاجِل تُحْيِي بِهِ مَا قَدْ مَات، وَتَرُدُّ بهِ مَا قَدْ فَاتَ، وَتُخْرِجُ بِهِ مَا هُوَ آت، وَتُوَسِّعُ بِهِ فِي الاَقْوَاتِ، سَحَاباً مُتَرَاكِماً هَنِيئاً مَرِيئاً طَبَقاً مُجَلْجَلاً غَيْرَ مُلِثٍّ وَدْقُهُ، وَلاَ خُلَّب بَرْقُهُ.
أللَّهُمَّ اسْقِنَا غَيْثاً مَغيثَاً مَرِيعاً مُمْرِعاً عَرِيْضَاً، وَاسِعاً غَزِيراً تَرُدُّ بِهِ النَّهِيضَ وَتَجْبُرُ بِهِ الْمَهِيضَ.
أللَّهُمَّ اسْقِنَا سَقْياً تُسِيلُ مِنْهُ الظِّرابَ، وَتَمْلا مِنْهُ الْجِبَابَ، وَتُفَجِّرُ بِهِ الانْهَارَ، وَتُنْبِتُ بِـهِ الاشْجَارَ وَتُرْخِصُ بِهِ الاسْعَارَ فِي جَمِيع الامْصَارِ، وَتَنْعَشُ بِهِ البَهَائِمَ وَالْخَلْقَ، وَتُكْمِلُ لَنَا بِهِ طَيِّبَاتِ الرِّزْقِ، وَتُنْبِتُ لَنَا بِهِ الزَّرْعَ، وَتُدِرُّ بِهِ الضَّرْعَ، وَتَزِيدُنَا بِهِ قُوَّةً إلَى قُوَّتِنَا.
أللَّهُمَّ لا تَجْعَلْ ظِلَّهُ عَلَيْنَا سَمُوماً وَلاَ تَجْعَلْ بَرْدَهُ عَلَيْنَا حُسُوماً، وَلاَ تَجْعَلْ صَوْبَهُ عَلَيْنَا رُجُوماً، وَلا تَجْعَلْ مَاءَهُ عَلَيْنَا اُجَاجـاً. أللَّهُمَّ صَلِّ عَلَى مُحَمَّد وَآلِ مُحَمَّد، وَارْزُقْنَا مِنْ بَرَكَاتِ السَّمَاوَاتِ وَالارْضِ، إنَّكَ عَلَى كُلِّ شَيْء قَدِيرٌ."""


